import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  assembleUpdates,
  assertNewerFeed,
  collectUpdates,
  updateTargets,
  verifyUpdate,
} from './updates.mjs';
import { assemble, collect, platforms } from './release.mjs';
import { verifyRelease } from './verify-release.mjs';

// Public interoperability vector from tauri-plugin-updater 2.14.0 offline_tests:
// generated by the official Tauri signer, payload "test", signed version 2.0.0.
const key = Buffer.from(
  'untrusted comment: minisign public key: A49EF4746FA6E6D7\nRWTX5qZvdPSepDGWg2bz8n6ArQnBMwgQK1geVosorcbLzcunD+KJ+cYe',
).toString('base64');
const rawSignature =
  'untrusted comment: signature from tauri secret key\nRUTX5qZvdPSepPF2zsjvP/L/TQtBLRnWRvaq+4omK1UEugtQp/USrGiI1v762sDy3id3aor7bRC9ETyeot6lMHHrWoZ5hjUM1Qc=\ntrusted comment: timestamp:1791649051\tfile:payload\tversion:2.0.0\nDDq2CLOEl5cQmC2eJRHlnZPVViOZsu1CjpPKQoei4A/XBfkDqGO0B+QMrcrHgEQ5qV3mne75tdFWhJpqUXh9AA==';
const signature = Buffer.from(rawSignature).toString('base64');
const version = '2.0.0',
  sha = 'a'.repeat(40);

test('official Tauri signature verifies; payload, version, key and trusted-comment tampering fail', () => {
  verifyUpdate(Buffer.from('test'), signature, key, version);
  assert.throws(
    () => verifyUpdate(Buffer.from('changed'), signature, key, version),
    /verification/,
  );
  assert.throws(() => verifyUpdate(Buffer.from('test'), signature, key, '9.9.9'), /version/);
  assert.throws(
    () =>
      verifyUpdate(
        Buffer.from('test'),
        Buffer.from(rawSignature.replace('file:payload', 'file:changed')).toString('base64'),
        key,
        version,
      ),
    /verification/,
  );
  assert.throws(() =>
    verifyUpdate(
      Buffer.from('test'),
      signature,
      Buffer.from('not a key').toString('base64'),
      version,
    ),
  );
  assert.throws(() => verifyUpdate(Buffer.from('test'), 'not a signature', key, version));
});

function fixture(fn) {
  const root = mkdtempSync(join(tmpdir(), 'desktop-updates-'));
  try {
    fn(root);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}
function populate(root) {
  for (const [platform, spec] of Object.entries(platforms)) {
    const bundle = join(root, 'bundle', platform),
      out = join(root, 'input', platform);
    mkdirSync(bundle, { recursive: true });
    for (const ext of new Set([...spec.extensions, updateTargets[platform].extension]))
      writeFileSync(join(bundle, `app.${ext}`), 'test');
    writeFileSync(join(bundle, `app.${updateTargets[platform].extension}.sig`), signature);
    collect(bundle, out, version, platform, sha);
    collectUpdates(bundle, out, version, platform, sha, key, false);
  }
  assemble(join(root, 'input'), join(root, 'out'), version, sha);
}

test('complete matrix creates four authenticated updater targets alongside all five installers', () =>
  fixture((root) => {
    populate(root);
    assembleUpdates(join(root, 'input'), join(root, 'out'), version, sha, key);
    const feed = JSON.parse(readFileSync(join(root, 'out/latest.json')));
    assert.deepEqual(Object.keys(feed.platforms).sort(), [
      'darwin-aarch64',
      'darwin-x86_64',
      'linux-x86_64',
      'windows-x86_64',
    ]);
    assert.match(
      feed.platforms['darwin-aarch64'].url,
      /desktop-v2.0.0\/Minion-Hub_2.0.0_macos-arm64.app.tar.gz$/,
    );
    assert.equal(feed.platforms['linux-x86_64'].signature, signature);
    assert.equal(JSON.parse(readFileSync(join(root, 'out/desktop-manifest.json'))).signed, false);
    assert.equal(
      JSON.parse(readFileSync(join(root, 'out/desktop-manifest.json'))).updaterIntegrity,
      true,
    );
    const sums = readFileSync(join(root, 'out/SHA256SUMS'), 'utf8');
    assert.match(sums, /latest.json/);
    assert.match(sums, /app.tar.gz.sig/);
    assert.deepEqual(verifyRelease(join(root, 'out'), version, key), {
      version,
      installers: 5,
      updaterTargets: 4,
    });
    writeFileSync(join(root, 'out', 'unverified-extra.exe'), 'unexpected');
    assert.throws(() => verifyRelease(join(root, 'out'), version, key), /Unverified extra/);
    rmSync(join(root, 'out', 'unverified-extra.exe'));
    writeFileSync(join(root, 'out', 'latest.json'), '{}');
    assert.throws(() => verifyRelease(join(root, 'out'), version, key), /identity/);
  }));

test('missing matrix, changed files, wrong keys and wrong source receipts block feed assembly', () =>
  fixture((root) => {
    populate(root);
    const path = join(root, 'input/linux-x64/updater-linux-x64.json');
    const receipt = JSON.parse(readFileSync(path));
    writeFileSync(path, JSON.stringify({ ...receipt, sourceSha: 'b'.repeat(40) }));
    assert.throws(
      () => assembleUpdates(join(root, 'input'), join(root, 'out'), version, sha, key),
      /identity/,
    );
    writeFileSync(path, JSON.stringify(receipt));
    assert.throws(
      () => assembleUpdates(join(root, 'input'), join(root, 'out'), version, sha, 'other'),
      /identity/,
    );
    writeFileSync(join(root, 'input/linux-x64', receipt.name), 'tampered');
    assert.throws(
      () => assembleUpdates(join(root, 'input'), join(root, 'out'), version, sha, key),
      /digest/,
    );
    rmSync(path);
    assert.throws(() => assembleUpdates(join(root, 'input'), join(root, 'out'), version, sha, key));
  }));

test('feed advances only to a strictly newer numeric semantic version', () => {
  assertNewerFeed(null, { version: '0.0.2' });
  assertNewerFeed({ version: '1.9.9' }, { version: '1.10.0' });
  assertNewerFeed({ version: '1.9.9' }, { version: '2.0.0' });
  for (const version of ['1.9.9', '1.9.8', '0.99.99', '2.0.0-rc1', '2.0.0\n'])
    assert.throws(() => assertNewerFeed({ version: '1.9.9' }, { version }));
});
